-- 38_exercise_library.sql
-- To be applied as migration 38_exercise_library. Generated by supabase/tools/import_exercemus.py;
-- edit the script and re-run it rather than editing this file.
--
-- Exercise data from https://github.com/exercemus/exercises (MIT), commit 0ee5b742928b0c910883fa1c0c2cfaf26c4ee180:
-- names and other names, muscles and equipment for every strength-type exercise (strength,
-- olympic weightlifting, strongman, calisthenics). No instructions, tips, images or videos.
--
-- 1. Three new columns on lift_exercises: muscles (main), muscles_also (secondary), equipment,
--    each from exercemus's own lists, so a muscle is always one of the 21 it names.
-- 2. 70 lifts we already have get their muscles and equipment, and exercemus's names for them
--    become other names (search "Barbell Bench Press" and you find Bench Press).
-- 3. 600 new lifts, each with one main name; names that mean the same lift are its other names.
--    A new lift whose name (or other name) is already in the catalogue is skipped.
-- Nothing is renamed or deleted, and no one's sets change.

alter table public.lift_exercises
  add column if not exists muscles text[] not null default '{}',
  add column if not exists muscles_also text[] not null default '{}',
  add column if not exists equipment text[] not null default '{}';
alter table public.lift_exercises drop constraint if exists lift_exercises_muscles_known;
alter table public.lift_exercises add constraint lift_exercises_muscles_known check (
  muscles <@ array['forearms', 'abductors', 'adductors', 'middle back', 'neck', 'biceps', 'shoulders', 'serratus anterior', 'chest', 'triceps', 'abs', 'calves', 'glutes', 'traps', 'quads', 'hamstrings', 'lats', 'brachialis', 'obliques', 'soleus', 'lower back']::text[] and muscles_also <@ array['forearms', 'abductors', 'adductors', 'middle back', 'neck', 'biceps', 'shoulders', 'serratus anterior', 'chest', 'triceps', 'abs', 'calves', 'glutes', 'traps', 'quads', 'hamstrings', 'lats', 'brachialis', 'obliques', 'soleus', 'lower back']::text[]
  and equipment <@ array['none', 'ez curl bar', 'barbell', 'dumbbell', 'gym mat', 'exercise ball', 'medicine ball', 'pull-up bar', 'bench', 'incline bench', 'kettlebell', 'machine', 'cable', 'bands', 'foam roll', 'other']::text[]
  and cardinality(muscles) <= 8 and cardinality(muscles_also) <= 12 and cardinality(equipment) <= 6);

create temp table x (name text, ours boolean, aliases text[], muscles text[], muscles_also text[], equipment text[], bw boolean, log_type text) on commit drop;

-- Lifts we have: fill in what they work and need (only where nothing is recorded yet).
update public.lift_exercises e set muscles = x.muscles, muscles_also = x.muscles_also, equipment = x.equipment
  from x where x.ours and lower(btrim(e.name)) = lower(btrim(x.name)) and e.deleted_at is null and e.muscles = '{}';

-- New lifts: skip any whose name or other name is already a lift or another lift's other name.
select x.name, 'strength', x.log_type, x.bw, x.muscles, x.muscles_also, x.equipment from x
 where not x.ours
   and not exists (select 1 from public.lift_exercises e where e.deleted_at is null and lower(btrim(e.name)) = any (select lower(btrim(n)) from unnest(x.name || x.aliases) n))
   and not exists (select 1 from public.lift_exercise_aliases a where a.deleted_at is null and lower(btrim(a.alias)) = any (select lower(btrim(n)) from unnest(x.name || x.aliases) n));

-- Other names: each points at its lift, unless it's already some lift's name or other name.
select distinct on (lower(btrim(al))) e.id, al from x cross join lateral unnest(x.aliases) al
  join public.lift_exercises e on lower(btrim(e.name)) = lower(btrim(x.name)) and e.deleted_at is null
 where not exists (select 1 from public.lift_exercises o where o.deleted_at is null and lower(btrim(o.name)) = lower(btrim(al)))
   and not exists (select 1 from public.lift_exercise_aliases a where a.deleted_at is null and lower(btrim(a.alias)) = lower(btrim(al)))
 order by lower(btrim(al));
